semaphore mutex = 1;   // 缓冲区互斥
semaphore empty = n;   // 空闲缓冲区数，初值 n
semaphore full  = 0;   // 产品数，初值 0

producer() {
    while (1) {
        produce an item;
        P(empty);          // 先申请空槽
        P(mutex);          // 再进入临界区
        put item into buffer;
        V(mutex);          // 先退出临界区
        V(full);           // 再通知消费者
    }
}

consumer() {
    while (1) {
        P(full);           // 先申请产品
        P(mutex);
        take item from buffer;
        V(mutex);
        V(empty);          // 通知生产者有空槽
        consume the item;
    }
}
